arguments.command:
cat > tests/overlap_test.sh <<'EOF'
#!/bin/bash
# ROOM-12: overlapping bookings in the same room are rejected and not written.
fail=0
f=$(mktemp)
b() { BOOKINGS=$f bash bin/book "$@" 2>&1; }
b A 0900 1000 first >/dev/null
lines() { wc -l < "$f"; }

b A 0930 1030 overlap >/dev/null && { echo "overlap accepted"; fail=1; }
b A 0800 0930 overlap-head >/dev/null && { echo "head overlap accepted"; fail=1; }
b A 0900 1000 same >/dev/null && { echo "identical accepted"; fail=1; }
b A 0830 1100 contains >/dev/null && { echo "containing accepted"; fail=1; }
b A 0915 0945 inside >/dev/null && { echo "inside accepted"; fail=1; }
[ "$(lines)" -eq 1 ] || { echo "file written on overlap"; fail=1; }

b A 1000 1100 adjacent-after >/dev/null || { echo "adjacent after rejected"; fail=1; }
b A 0800 0900 adjacent-before >/dev/null || { echo "adjacent before rejected"; fail=1; }
b B 0900 1000 other-room >/dev/null || { echo "other room rejected"; fail=1; }
[ "$(lines)" -eq 4 ] || { echo "expected 4 lines"; fail=1; }
rm -f "$f"
exit $fail
EOF
python3 - <<'EOF'
p='bin/book'
s=open(p).read()
s=s.replace("printf '%s","""if [ -f "$file" ]; then
  conflict=$(awk -F'\\t' -v r="$room" -v s="$start" -v e="$end" '$1 == r && (s+0) < ($3+0) && ($2+0) < (e+0) { print $2 "-" $3; exit }' "$file")
  if [ -n "$conflict" ]; then
    echo "error: $room is already booked $conflict" >&2
    exit 1
  fi
fi
printf '%s""",1)
open(p,'w').write(s)
EOF
mkdir notes; printf '# ROOM-12\n\nbin/book: 同じ部屋で [開始,終了) が重なる予約はエラー(exit 1)にし、ファイルに書かない。終了時刻ちょうどの開始は許可。時刻は awk で数値比較（0900 の8進問題を避ける）。\nテスト: tests/overlap_test.sh\n' > notes/ROOM-12.md
bash scripts/verify.sh; echo rc=$?

